from taf.ul.ettf.sim.core.command import Command
from taf.ul.ettf.sim.core.library import State
from taf.ul.ettf.typed.custom_types import AnyOf
from taf.ul.ettf.typed.typed import typed
from taf.ul.ettf.utils.exception import LibraryError


class DirectionLayerTypeError(LibraryError):
    pass


class CommonOptions(State):
    @typed(id=int)
    def with_id(self, id):
        self.append_command_attribute('id', id)

    @typed(delay=int)
    def with_delay(self, delay):
        self.append_command_attribute('delay', delay)

    @staticmethod
    @typed(retry=int)
    def with_retry(retry):
        Command.command_elements.add_modulator('retry', retry)

    def with_type(self, type):
        self.append_command_attribute('type', type)

    def with_scell(self, scell):
        self.append_command_attribute('scell', scell)

    def with_format(self, format):
        self.append_command_attribute('format', format)


class TypeOptions(object):
    EGATE_COMMAND_TYPE_DICT = {
        ('dl', 'physical'): 'pdsch',
        ('ul', 'physical'): 'pusch',
    }

    @staticmethod
    @typed(layer=AnyOf(['physical']))
    def with_layer(layer):
        Command.assemblers.add_assembler(TypeOptions.assemble_type)
        Command.command_elements.add_modulator('layer', layer)

    @staticmethod
    @typed(direction=AnyOf(['ul', 'dl']))
    def with_direction(direction):
        Command.assemblers.add_assembler(TypeOptions.assemble_type)
        Command.command_elements.add_modulator('direction', direction)

    @staticmethod
    def assemble_type():
        _type = Command.command_elements.get_param('type')
        _layer = Command.command_elements.get_modulator('layer')
        _direction = Command.command_elements.get_modulator('direction')

        if _type:
            return
        elif all([_layer, _direction]):
            try:
                Command.command_elements.add_param('type', TypeOptions.EGATE_COMMAND_TYPE_DICT[(_direction, _layer)])
            except KeyError:
                raise DirectionLayerTypeError('Incompatible direction and layer combination',
                                              'Use matching values from CommandOptionsAssembler')
        elif any([_layer, _direction]):
            raise DirectionLayerTypeError('Insufficient data',
                                          'Please specify both \'direction\' and \'layer\'')
